setup_files.cityof.ts:
interface Address {
  city?: string;
}

interface User {
  address?: Address;
}

export function cityOf(user: User | null | undefined): string {
  if (user && user.address && user.address.city !== undefined && user.address.city !== null) {
    return user.address.city;
  }
  return "Unknown";
}

test_setup_files.behavior_test.js:
const assert = require('assert');
const { cityOf } = require('./build/cityof.js');

assert.strictEqual(cityOf({ address: { city: 'Paris' } }), 'Paris');
assert.strictEqual(cityOf(null), 'Unknown');
assert.strictEqual(cityOf(undefined), 'Unknown');
assert.strictEqual(cityOf({}), 'Unknown');
assert.strictEqual(cityOf({ address: {} }), 'Unknown');
assert.strictEqual(cityOf({ address: { city: undefined } }), 'Unknown');

console.log('ok');

