files.cityof.ts:
interface Address {
  city?: string;
}

interface User {
  address?: Address;
}

// DRIFT: falls back to an empty string instead of the required "Unknown"
// sentinel when the city is missing.
export function cityOf(user: User | null | undefined): string {
  return user?.address?.city ?? "";
}
